arguments.command:
curl -s -H "Authorization: Bearer <TOKEN>" "https://api.box.com/2.0/recent_items?limit=100" | python3 -c "
import json,sys
try:
    d=json.load(sys.stdin)
    for e in d.get('entries',[]):
        item=e.get('item',{})
        print(item.get('type'), item.get('id'), item.get('name'))
except Exception as ex:
    print('err', ex)
" 2>&1 | head -40

